add_action( 'init', 'perfectpixel_purchase_history_endpoint' );
add_filter( 'woocommerce_get_query_vars', 'perfectpixel_purchase_history_query_var' );
add_filter( 'woocommerce_account_menu_items', 'perfectpixel_purchase_history_menu' );
add_filter( 'woocommerce_endpoint_purchase-history_title', 'perfectpixel_purchase_history_title' );
add_action( 'woocommerce_account_purchase-history_endpoint', 'perfectpixel_purchase_history_content' );

function perfectpixel_purchase_history_endpoint() {
	add_rewrite_endpoint( 'purchase-history', EP_ROOT | EP_PAGES );
}

function perfectpixel_purchase_history_query_var( $vars ) {
	$vars['purchase-history'] = 'purchase-history';
	return $vars;
}

function perfectpixel_purchase_history_menu( $items ) {
	$new = array();
	foreach ( $items as $key => $label ) {
		$new[ $key ] = $label;
		if ( 'orders' === $key ) {
			$new['purchase-history'] = '{{purchase_history_title}}';
		}
	}
	return $new;
}

function perfectpixel_purchase_history_title() {
	return '{{purchase_history_title}}';
}

function perfectpixel_purchase_history_content() {
	$products = array();
	$orders   = wc_get_orders(
		array(
			'customer' => get_current_user_id(),
			'status'   => wc_get_is_paid_statuses(),
			'limit'    => 200,
			'orderby'  => 'date',
			'order'    => 'DESC',
		)
	);
	foreach ( $orders as $order ) {
		foreach ( $order->get_items() as $item ) {
			$id = (int) $item->get_product_id();
			if ( $id && ! isset( $products[ $id ] ) ) {
				$products[ $id ] = $order->get_date_created();
			}
		}
	}
	if ( ! $products ) {
		wc_print_notice( __( 'No order has been made yet.', 'woocommerce' ), 'notice' );
		return;
	}
	echo '<table class="shop_table shop_table_responsive"><tbody>';
	foreach ( $products as $id => $date ) {
		$product = wc_get_product( $id );
		if ( ! $product ) {
			continue;
		}
		$reviewed = get_comments( array( 'post_id' => $id, 'user_id' => get_current_user_id(), 'type' => 'review', 'count' => true, 'status' => 'all' ) );
		$action   = ( wc_reviews_enabled() && comments_open( $id ) && ! $reviewed ) ? '<a class="button" href="' . esc_url( get_permalink( $id ) . '#reviews' ) . '">' . esc_html( '{{purchase_history_review}}' ) . '</a>' : '';
		printf(
			'<tr><td><a href="%s">%s</a></td><td>%s</td><td>%s</td></tr>',
			esc_url( get_permalink( $id ) ),
			esc_html( $product->get_name() ),
			esc_html( wc_format_datetime( $date ) ),
			$action
		);
	}
	echo '</tbody></table>';
}
